              if (param.Count > 0)
              {
                  var query = param.Aggregate("", (current, pair) => current + (current.Length == 0 ? "" : "&") + Uri.EscapeDataString(pair.Key) + "=" + Uri.EscapeDataString(pair.Value));
                  url += "?" + query;
              }

              using (HttpClient client = new HttpClient())
