public async Task Main()
          {
              // Parameter setup
              string appkey = "xxxx"; // Client authorization key
              string secretKey = "xxxx"; // Secret key
              var param = new Dictionary<string, string>
              {
                  { "keyword", "亿企查" } // Enterprise related keyword (please enter more than 2 characters)
              };
              string timestamp = (DateTime.UtcNow.ToBinary() / 10000000 + 62135596800).ToString("D13"); // Generate millisecond timestamp
              string sign = GetMd5(appkey + timestamp + secretKey).ToLower();

              var headers = new Dictionary<string, string>
              {
                  { "Content-Type", "application/x-www-form-urlencoded; charset=UTF-8" },
                  { "Auth-Version", "v1" },
                  { "appkey", appkey },
                  { "timestamp", timestamp },
                  { "sign", sign }
              };
              //{domain} 替换成真实域名
              string url = "http://{domain}/gateway/api-server/associationRelation/ownershipStructure"; // Fuzzy search

              // Add query parameters if they exist
              if (param.Count > 0)
              {
                  var query = param.Aggregate("", (current, pair) => current + (current.Length == 0 ? "" : "&") + Uri.EscapeDataString(pair.Key) + "=" + Uri.EscapeDataString(pair.Value));
                  url += "?" + query;
              }

              using (HttpClient client = new HttpClient())
              {
                  HttpResponseMessage response = await client.GetAsync(url);

                  if (response.IsSuccessStatusCode)
                  {
                      var result = await response.Content.ReadAsStringAsync();
                      Console.WriteLine("--- Print Result ---");
                      dynamic data = JsonConvert.DeserializeObject(result);
                      Console.WriteLine(data);
                  }
                  else
                  {
                      Console.WriteLine("Failed to get data.");
                  }
              }
          }

          private static string GetMd5(string input)
          {
              using (System.Security.Cryptography.MD5 md5 = System.Security.Cryptography.MD5.Create())
              {
                  byte[] inputBytes = Encoding.ASCII.GetBytes(input);
                  byte[] hashBytes = md5.ComputeHash(inputBytes);

                  StringBuilder sb = new StringBuilder();
                  foreach (byte b in hashBytes)
                  {
                      sb.Append(b.ToString("X2"));
                  }
                  return sb.ToString();
              }
          }

