import cn.hutool.crypto.SecureUtil;
          import org.apache.commons.lang3.StringUtils;

          import java.io.BufferedReader;
          import java.io.InputStreamReader;
          import java.net.HttpURLConnection;
          import java.net.URL;
          import java.net.URLEncoder;
          import java.nio.charset.StandardCharsets;

          public class ApiClient {

              public static void main(String[] args) {
                  String appkey = "xxxx"; // 客户授权key
                  String secretKey = "xxxx"; // 密钥
                  String keyword = "亿企查"; // 企业相关关键词

                  try {
                      String timestamp = String.valueOf(System.currentTimeMillis()); // 生成毫秒时间戳
                      String sign = getSign(appkey, timestamp, secretKey);

                      String url = "http://{domain}/gateway/api-server/intellectual/entCopyrightList?keyword=" + URLEncoder.encode(keyword, "UTF-8");

                      HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
                      connection.setRequestMethod("GET");

                      // 设置HTTP头
                      connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded; charset=UTF-8");
                      connection.setRequestProperty("Auth-Version", "v1");
                      connection.setRequestProperty("appkey", appkey);
                      connection.setRequestProperty("timestamp", timestamp);
                      connection.setRequestProperty("sign", sign);

                      // 读取响应
                      BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8));
                      StringBuilder response = new StringBuilder();
                      String line;
                      while ((line = reader.readLine()) != null) {
                          response.append(line);
                      }
                      reader.close();

                      // 打印结果
                      System.out.println("---打印结果---");
                      System.out.println(response.toString());

                  } catch (Exception e) {
                      e.printStackTrace();
                  }
              }

              // 生成签名
              private static String getSign(String appkey, String timestamp, String secretKey) {
                  return StringUtils.lowerCase(SecureUtil.md5(appkey + timestamp + secretKey));
              }
          }

